info.features:
[
    {
        "icon": "CheckCircleIcon",
        "subtext": "Conversational Analytics",
        "description": "Get a bird’s-eye view of inbound and outbound communication, with insights on agent, channel, and team-specific performance, as well as response and closure analytics."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Segmented Channel-Specific Daily Analytics",
        "description": "Drill down into the number of inbound and outbound messages and conversations handled by each channel, broken down by hour and day."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Campaign Analytics",
        "description": "Monitor campaign delivery, read rates, and response rates, along with user-specific responses. View analytics online or download data for further analysis."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "BOT Analytics",
        "description": "Track BOT flow execution to determine if success criteria are met, providing visibility into BOT performance and customer interactions."
    }
]

[
    {
        "icon": "CheckCircleIcon",  
        "subtext": "Intuitive BOT Flow Builder",
        "description": "Create bots using an extremely user-friendly, UI-based BOT flow builder."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Quick Deployment",
        "description": "Build and deploy bots within minutes to drive seamless customer engagement."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Event-Driven and Timed Responses",
        "description": "Set bots to respond to specific events and include time-delayed responses as needed."
    }
]

[
    {
        "icon": "CheckCircleIcon",  
        "subtext": "Effortless Cohort Creation",
        "description": "Easily create cohorts from the Customer Management module."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Reusable Cohorts",
        "description": "Use cohorts on demand in outbound campaigns for lead management, customer engagement, or marketing."
    }
]

[
    {
        "icon": "CheckCircleIcon",  
        "subtext": "Cohort Creation",
        "description": "Build customer cohorts from your customer management module using dynamic filters, session tags from conversations, or external data sources."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Flexible Campaign Execution",
        "description": "Run campaigns on demand or schedule them for optimal dates and times to suit your customers."
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "A/B Testing",
        "description": "Test campaign effectiveness by running A/B campaigns with a small test group before rolling out to a larger audience."
    }
]

[
    {
        "icon": "CheckCircleIcon",  
        "subtext": "Centralized Inbox for All Channels",
        "description": "Communicate with customers on WhatsApp, Messenger, Instagram DM, Telegram"
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Predefined Message Templates",
        "description": "Start new conversations or continue existing ones using predefined messages"
    },
    {
        "icon": "CheckCircleIcon",
        "subtext": "Prioritization",
        "description": "Enable team members to prioritize conversations based on time unattended or unanswered, minimizing customer wait times"
    }
]
